const fn = new Function(code + "\nreturn { hasShape };");
const { hasShape } = fn();
const spec = { id: "string", qty: "number" };
if (hasShape({ id: "a", qty: 2 }, spec) !== true) throw new Error("Exact match accepted.");
if (hasShape({ id: "a", qty: 2, extra: true }, spec) !== true) throw new Error("Structural typing: extra fields allowed.");

const fn = new Function(code + "\nreturn { hasShape };");
const { hasShape } = fn();
const spec = { id: "string", qty: "number" };
if (hasShape({ id: 7, qty: 2 }, spec) !== false) throw new Error("Wrong typeof fails.");
if (hasShape({ id: "a" }, spec) !== false) throw new Error("Missing fields fail.");
if (hasShape(null, spec) !== false) throw new Error("null is not an object here.");
